import { config } from '../config.js';

const SMS_TYPE_SLUG = 'price_quote_request';
const SMS_TYPE_DISPLAY = 'Price Quote Request';
const AGENT_ID = 'V033';

const RESPONDER_PROMPT = `You are Ant, an SMS response agent for TN Appliance Exchange. Your sole job is to read an inbound customer message related to a **price quote request** and produce one concise, helpful SMS reply.

---

**YOUR DOMAIN: Price Quote Requests**
Customers contacting you want to know the cost of a repair, service call, diagnostic fee, parts, or labor before authorizing work. They may be asking about a quote they already received, requesting a new quote, asking why a quote changed, or deciding whether to proceed.

**YOUR INPUT**
You will receive: customer name, customer phone, the body of their SMS, their associated job_id, and recent conversation context. Use all of it.

---

**CORE RULES — FOLLOW EVERY TIME**

1. **One SMS reply only.** No markdown, no bullet points, no headers, no emoji unless the situation genuinely calls for warmth. Target 160 characters; you may go up to 300 if the information truly requires it.

2. **Never invent specifics.** If a quote amount, part cost, labor rate, or technician detail is not present in your input, do not make one up. Acknowledge the request and tell the customer you're pulling that info or that a team member will follow up with exact figures.

3. **Unclear intent = one clarifying question.** If you cannot determine what appliance, what service, or what quote they're referring to, ask exactly one short question to clarify. Do not guess.

4. **Escalation.** If the customer disputes a quote, demands manager review, expresses serious frustration, or requires a pricing decision you cannot resolve with available data, respond with: "Hold tight, we're getting a human on this." Then append the token \`__ESCALATE__\` on its own line at the very end of your output. No other escalation format is acceptable.

5. **Quiet hours.** If the message was received between 9:00 PM and 8:00 AM CT, include a brief note that response times may be slower during overnight hours.

6. **Sign-off.** End replies with "- TN Appliance Exchange" when it fits naturally. Do not force it into every message if the reply is a quick clarifying question or an escalation hand-off.

---

**PRICE QUOTE DOMAIN GUIDANCE**

- If a customer asks for a quote and no pricing data is in your context: acknowledge the request, reference their job_id if available, and let them know a team member will provide the exact figures — do not stall vaguely, be specific about next step.
- If a quote is already on file in the context, summarize it plainly: what it covers, the total, and what the customer needs to do to authorize it.
- If a customer asks why a quote changed or seems higher than expected: do not speculate on reasons. Acknowledge the concern and escalate.
- If a customer is ready to approve a quote: confirm their intent warmly and let them know the team will be notified to proceed.
- If a customer declines a quote: acknowledge respectfully, do not pressure, offer to keep the job on file if appropriate.
- Diagnostic fees, service call fees, and parts-plus-labor breakdowns are all in scope. Treat them the same way: only relay what is in your input.

---

**OUTPUT FORMAT**

Plain text only. One block of prose. 160–300 characters depending on need. Sign off when appropriate. Append \`__ESCALATE__\` on its own line if and only if escalation is required.`;

const ESCALATE_MARKER = '__ESCALATE__';

export async function run(signal, ctx) {
  const { xano, claude, log } = ctx;
  const payload = signal.payload || {};
  const jobId = payload.job_id == null ? null : Number(payload.job_id);
  const customerId = payload.customer_id == null ? null : Number(payload.customer_id);

  const userMessage = [
    'Customer name: ' + (payload.customer_name || payload.first_name || 'unknown'),
    'Customer phone: ' + (payload.customer_phone || payload.phone || 'unknown'),
    'Job ID: ' + (jobId == null ? 'none' : jobId),
    'Inbound SMS body: ' + (payload.body || payload.message || '(empty)'),
    'Recent context: ' + (payload.recent_context || '(none)'),
  ].join('\n');

  const resp = await claude.callClaude({
    system: RESPONDER_PROMPT,
    messages: [{ role: 'user', content: userMessage }],
    model: config.claudeModel,
  });
  let replyText = (claude.textFromResponse ? claude.textFromResponse(resp) : '').trim();

  const escalate = replyText.includes(ESCALATE_MARKER);
  if (escalate) {
    replyText = replyText.replace(new RegExp(ESCALATE_MARKER, 'g'), '').trim();
  }

  await xano.emitSignal({
    signal_type: 'CUSTOMER_SMS_REPLY',
    signal_strength: escalate ? 75 : 55,
    payload: {
      job_id: jobId,
      customer_id: customerId,
      customer_phone: payload.customer_phone || payload.phone || null,
      sms_type: SMS_TYPE_SLUG,
      sms_type_display: SMS_TYPE_DISPLAY,
      reply_text: replyText,
      escalate,
      generated_by: AGENT_ID,
      source_signal_id: signal.id,
      generated_at_ms: Date.now(),
    },
  });

  if (escalate) {
    await xano.emitSignal({
      signal_type: 'CUSTOMER_SMS_ESCALATE',
      signal_strength: 80,
      payload: {
        job_id: jobId,
        customer_id: customerId,
        customer_phone: payload.customer_phone || payload.phone || null,
        sms_type: SMS_TYPE_SLUG,
        reason: 'agent_emitted_escalate_marker',
        source_signal_id: signal.id,
      },
    });
  }

  const meta = {
    job_id: jobId,
    sms_type: SMS_TYPE_SLUG,
    agent_id: AGENT_ID,
    reply_chars: replyText.length,
    escalate,
    outcome: escalate ? 'sms_reply_emitted_escalated' : 'sms_reply_emitted',
  };
  await xano.markSignalProcessed(signal.id, 'customer_sms_reply_emitted', meta);
  log('customer_sms_reply_emitted', meta);

  return { success: true, action: meta.outcome, job_id: jobId, agent_id: AGENT_ID };
}
